class ReviewsCarousel{constructor(){this.currentIndex=0,this.reviewsPerView=this.calculateReviewsPerView(),this.totalReviews=8,this.maxIndex=Math.max(0,this.totalReviews-this.reviewsPerView),this.autoplayInterval=null,this.init(),this.setupEventListeners()}calculateReviewsPerView(){const e=window.innerWidth;return e>=1200?3:1}init(){this.measureCardWidth(),this.renderDots(),this.updateCarousel()}measureCardWidth(){const e=document.querySelector(".review-card");this.cardWidth=e.offsetWidth+25}renderDots(){const e=document.getElementById("carouselDots"),t=this.maxIndex+1;e.innerHTML=Array.from({length:t},(e,t)=>`<div class="dot ${0===t?"active":""}" data-index="${t}"></div>`).join("")}updateCarousel(){document.getElementById("reviewsGrid").style.transform=`translateX(-${this.currentIndex*this.cardWidth}px)`,this.updateDots(),this.updateButtons()}updateDots(){document.querySelectorAll("#carouselDots .dot").forEach((e,t)=>{e.classList.toggle("active",t===this.currentIndex)})}updateButtons(){const e=document.getElementById("prevBtn"),t=document.getElementById("nextBtn");e.disabled=0===this.currentIndex,t.disabled=this.currentIndex===this.maxIndex}next(){this.currentIndex<this.maxIndex&&(this.currentIndex++,this.updateCarousel())}prev(){this.currentIndex>0&&(this.currentIndex--,this.updateCarousel())}goToSlide(e){this.currentIndex=Math.min(Math.max(0,e),this.maxIndex),this.updateCarousel()}setupEventListeners(){document.getElementById("nextBtn").addEventListener("click",()=>this.next()),document.getElementById("prevBtn").addEventListener("click",()=>this.prev()),document.getElementById("carouselDots").addEventListener("click",e=>{if(e.target.classList.contains("dot")){const t=parseInt(e.target.dataset.index);this.goToSlide(t)}}),window.addEventListener("resize",()=>{const e=this.calculateReviewsPerView();e!==this.reviewsPerView&&(this.reviewsPerView=e,this.maxIndex=Math.max(0,this.totalReviews-this.reviewsPerView),this.currentIndex=Math.min(this.currentIndex,this.maxIndex),this.measureCardWidth(),this.renderDots(),this.updateCarousel())});let e=0,t=!1;const s=document.getElementById("reviewsGrid");s.addEventListener("touchstart",s=>{e=s.touches[0].clientX,t=!0}),s.addEventListener("touchmove",e=>{t&&e.preventDefault()}),s.addEventListener("touchend",s=>{if(!t)return;t=!1;const n=s.changedTouches[0].clientX,i=e-n;Math.abs(i)>50&&(i>0?this.next():this.prev())})}}!function(){const e=document.getElementById("reviewsGrid");if(e)if("undefined"!=typeof IntersectionObserver){const s=new IntersectionObserver(e=>{e.some(e=>e.isIntersecting)&&(s.disconnect(),t())},{rootMargin:"200px"});s.observe(e)}else document.addEventListener("DOMContentLoaded",t);function t(){new ReviewsCarousel}}();